<template><article v-if="page" class="managed-page"><div :class="['page-hero',{'has-cover':page.coverUrl}]" :style="page.coverUrl?{backgroundImage:`url(${page.coverUrl})`}:{}"><div class="container"><p class="eyebrow">ZHONG BOSHI DENTAL</p><h1>{{page.title}}</h1><p v-if="page.summary">{{page.summary}}</p></div></div><div class="narrow managed-content wechat-content" v-html="page.contentHtml"></div></article><div v-else class="state-card container">{{error || '正在加载页面…'}}</div></template>
<script setup lang="ts">import { onMounted,ref,watch } from 'vue';import { useRoute } from 'vue-router';import { WebsitePage,websiteApi } from '../api';import { setSeo } from '../site';const route=useRoute();const page=ref<WebsitePage|null>(null),error=ref('');async function load(){page.value=null;error.value='';try{page.value=await websiteApi.page(String(route.params.slug));setSeo({title:page.value.seoTitle||`${page.value.title}｜重庆种博士口腔`,description:page.value.seoDescription||page.value.summary,image:page.value.coverUrl,canonicalPath:route.path});}catch(e){error.value=e instanceof Error?e.message:'页面加载失败';}}onMounted(load);watch(()=>route.params.slug,load);</script>
